import type { VocabExclusionReason, VocabOriginalContent } from '../vocabContent';

type Level = VocabOriginalContent['level'];

let seq = 0;
/** 1語分。level は語ごとに異なるため引数で受け取る */
const w = (
  surface: string, reading: string, level: Level, pos: string[],
  glossZh: string, exampleJa: string, exampleZh: string,
  collocationsJa: string[] = [], confusableSurfaces: string[] = [],
  extra: {
    senseNoteZh?: string; usageNoteZh?: string;
    /** active_beta の必須項目（FINAL CLOSEOUT 要件B）。自社で書いた日本語・中国語の解説 */
    explanationJa?: string; explanationZh?: string;
  } = {},
): VocabOriginalContent => {
  seq += 1;
  return {
    wordId: `vc-03-${String(seq).padStart(3, '0')}`,
    surface, reading, level, pos,
    glossZh, exampleJa, exampleZh,
    collocationsJa, confusableSurfaces,
    state: 'draft', reviewNotes: [], batchNo: 3,
    ...extra,
  };
};

