/**
 * 検査を通った語だけ active_beta へ昇格させ、通らなかった語は理由つきで CORE から外す。
 * **最終状態は active_beta か excluded_from_core の2つだけ**（保留は残さない）。
 * 検査結果: docs/ai-course/adventure-v2/generated/vocab-content-validation-03.json
 */
export const CORE_BATCH_03: VocabOriginalContent[] = DRAFT.map((c) => {
  const key = `${c.surface}|${c.reading}`;
  const reason = EXCLUDED_FROM_CORE[key];
  return reason
    ? {
      ...c,
      state: 'excluded_from_core' as const,
      exclusionReason: reason,
      reviewNotes: [REVIEW_NOTES[key] ?? '教材化できないため CORE から外した'],
    }
    : { ...c, state: 'active_beta' as const };
});
